create extension if not exists pgtap with schema extensions;
begin;
select no_plan();
select ok(not has_function_privilege('authenticated','public.reserve_planning_request(uuid,uuid,text)','EXECUTE'),'legacy admission disabled');
select ok(not has_function_privilege('atelier_planning_writer','private.append_planning_revision(uuid,jsonb)','EXECUTE'),'ID-only save disabled');
select ok(not has_function_privilege('atelier_planning_writer','private.release_planning_request(uuid)','EXECUTE'),'ID-only release disabled');
select ok(not has_function_privilege('authenticated','private.renew_planning_request(uuid,uuid)','EXECUTE'),'browser cannot renew');
select ok(not has_function_privilege('atelier_planning_writer','private.lock_planning_lease(uuid,uuid)','EXECUTE'),'internal locking helper private');
insert into auth.users(id,email) values('81000000-0000-4000-8000-000000000001','lease-owner@example.test');
insert into public.accounts(id,name,created_by) values('82000000-0000-4000-8000-000000000001','Lease account','81000000-0000-4000-8000-000000000001');
insert into public.account_memberships(account_id,user_id,role) values('82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','owner');
create temp table lease_fixture(k text primary key,v uuid);
grant all on lease_fixture to authenticated;
create function pg_temp.f(text) returns uuid language sql as 'select v from lease_fixture where k=$1';
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',true);
with p as(select * from public.create_product_with_revision('Lease product')) insert into lease_fixture select 'p',product_id from p union all select 'r',revision_id from p;
insert into lease_fixture values('lease',public.reserve_planning_request(pg_temp.f('p'),pg_temp.f('r'),'lease','83000000-0000-4000-8000-000000000001'));
reset role;
select is((select hard_deadline-created_at from private.planning_requests where id=pg_temp.f('lease')),interval '17 minutes','hard deadline is seventeen minutes');
select is((select expires_at-created_at from private.planning_requests where id=pg_temp.f('lease')),interval '120 seconds','initial lease unchanged');
select ok((select holder_token_hash=extensions.digest('83000000-0000-4000-8000-000000000001','sha256') from private.planning_requests where id=pg_temp.f('lease')),'only hash persisted');
select throws_ok($$update private.planning_requests set hard_deadline=hard_deadline+interval '1 second' where id=pg_temp.f('lease')$$,'22023',null,'deadline immutable');
select throws_ok($$update private.planning_requests set created_at=created_at+interval '1 second' where id=pg_temp.f('lease')$$,'22023',null,'creation time immutable');
select throws_ok($$select private.renew_planning_request(pg_temp.f('lease'),gen_random_uuid())$$,'42501',null,'wrong holder cannot renew');
select throws_ok($$select private.append_planning_revision(pg_temp.f('lease'),gen_random_uuid(),'{}')$$,'42501',null,'wrong holder cannot save');
select throws_ok($$select private.release_planning_request(pg_temp.f('lease'),gen_random_uuid())$$,'42501',null,'wrong holder cannot cancel');
update private.planning_requests set expires_at=clock_timestamp()+interval '10 seconds' where id=pg_temp.f('lease');
select lives_ok($$select private.renew_planning_request(pg_temp.f('lease'),'83000000-0000-4000-8000-000000000001')$$,'first renewal succeeds');
select lives_ok($$select private.renew_planning_request(pg_temp.f('lease'),'83000000-0000-4000-8000-000000000001')$$,'second renewal succeeds');
select ok((select expires_at>clock_timestamp()+interval '115 seconds' from private.planning_requests where id=pg_temp.f('lease')),'renewal extends current lease');
update public.account_memberships set role='member' where user_id='81000000-0000-4000-8000-000000000001';
select throws_ok($$select private.renew_planning_request(pg_temp.f('lease'),'83000000-0000-4000-8000-000000000001')$$,'P0002',null,'revocation fences renewal');
update public.account_memberships set role='owner' where user_id='81000000-0000-4000-8000-000000000001';
select private.release_planning_request(pg_temp.f('lease'),'83000000-0000-4000-8000-000000000001');
select throws_ok($$select private.renew_planning_request(pg_temp.f('lease'),'83000000-0000-4000-8000-000000000001')$$,'42501',null,'cancelled reservation cannot renew');
select throws_ok($$update private.planning_requests set completed_at=null where id=pg_temp.f('lease')$$,'22023',null,'terminal reservation cannot reopen');
-- Controlled historical fixture simulates reaching the immutable deadline, without waiting seventeen minutes.
insert into private.planning_requests(id,owner_id,product_id,expected_revision_id,request_key,created_at,expires_at,holder_token_hash)
values('84000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001',pg_temp.f('p'),pg_temp.f('r'),'deadline',clock_timestamp()-interval '16 minutes 30 seconds',clock_timestamp()+interval '20 seconds',extensions.digest('83000000-0000-4000-8000-000000000001','sha256'));
select private.renew_planning_request('84000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001');
select ok((select expires_at=hard_deadline from private.planning_requests where request_key='deadline' and owner_id='81000000-0000-4000-8000-000000000001'),'renewal capped at hard deadline');
insert into private.planning_requests(id,owner_id,product_id,expected_revision_id,request_key,created_at,expires_at,holder_token_hash)
values('84000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000001',pg_temp.f('p'),pg_temp.f('r'),'expired',clock_timestamp()-interval '18 minutes',clock_timestamp()-interval '2 minutes',extensions.digest('83000000-0000-4000-8000-000000000001','sha256'));
select throws_ok($$select private.renew_planning_request('84000000-0000-4000-8000-000000000002','83000000-0000-4000-8000-000000000001')$$,'42501',null,'hard-expired cannot renew');
select throws_ok($$select private.append_planning_revision('84000000-0000-4000-8000-000000000002','83000000-0000-4000-8000-000000000001','{}')$$,'42501',null,'hard-expired cannot save');
select is((select count(*) from public.product_revisions where product_id=pg_temp.f('p')),1::bigint,'failures preserve revision count');
select * from finish();
rollback;
